<summary>Click to reveal reference solution</summary>

```c
int set_bit(int n, int bit_pos) {
    return n | (1 << bit_pos);
}

int clear_bit(int n, int bit_pos) {
    return n & ~(1 << bit_pos);
}

int is_bit_set(int n, int bit_pos) {
    return ((n & (1 << bit_pos)) != 0) ? 1 : 0;
}

int count_set_bits(unsigned int n) {
    int count = 0;
    while (n > 0) {
        count += (n & 1);
        n >>= 1;
    }
    return count;
}
```
