<summary>Click to reveal reference solution</summary>

```c
#include <stdio.h>

int write_text_file(const char *path, const char *content) {
    if (path == 0 || content == 0) return -1;
    FILE *f = fopen(path, "w");
    if (f == 0) return -1;
    fputs(content, f);
    fclose(f);
    return 0;
}

int count_lines_in_file(const char *path) {
    if (path == 0) return -1;
    FILE *f = fopen(path, "r");
    if (f == 0) return -1;
    int lines = 0;
    int ch;
    while ((ch = fgetc(f)) != EOF) {
        if (ch == '\n') {
            lines++;
        }
    }
    fclose(f);
    return lines;
}
```
