#include <stdio.h>
#include <stddef.h>

int safe_format_user(char *dest, size_t dest_size, const char *username, int user_id) {
    if (dest == 0 || dest_size == 0 || username == 0) return -1;
    return snprintf(dest, dest_size, "User: %s (ID: %d)", username, user_id);
}

int safe_get_element(const int *arr, int len, int index, int *out_val) {
    if (arr == 0 || out_val == 0 || index < 0 || index >= len) {
        return -1;
    }
    *out_val = arr[index];
    return 0;
}
